func:
// Garantir que lemos a vaga quer venha encapsulada em 'results' ou não
let vaga = msg.payload.results ? msg.payload.results : msg.payload;

// 1. Guardamos a vaga original num "bolso" seguro chamado msg.vaga_original
msg.vaga_original = vaga;

// 2. Limpamos o código postal (exatamente igual ao teu regexReplace do KNIME)
let localizacao = vaga.locationName || "";
let cp = localizacao.replace(/[^a-zA-Z0-9]/g, "");

// 3. Criamos o URL dinâmico para o nó HTTP
msg.url = "https://api.postcodes.io/postcodes/" + cp;

return msg;

// 1. Recuperar a vaga original do "bolso"
let vaga = msg.vaga_original;

// 2. Extrair o país da resposta da API (postcodes.io)
let pais = "United Kingdom"; // Valor de salvaguarda caso a API falhe
if (msg.payload && msg.payload.result && msg.payload.result.country) {
    pais = msg.payload.result.country;
}

// 3. Substituir o código postal pelo país descoberto
vaga.locationName = pais;

// 4. Restaurar o payload com a vaga atualizada
msg.payload = vaga;

return msg;

let vaga = msg.payload.results ? msg.payload.results : msg.payload;

let salario_libras = vaga.minimumSalary || vaga.maximumSalary || 0;

// 1. FILTRO DE QUALIDADE (Gatekeeper)
if (salario_libras === 0 || !vaga.jobTitle) {
    return null; // Descarta anúncios inválidos e pára o fluxo
}

// 2. NORMALIZAÇÃO DE SALÁRIOS (Lógica Inteligente)
if (salario_libras > 0 && salario_libras < 100) {
    salario_libras = salario_libras * 1950;
} else if (salario_libras >= 100 && salario_libras <= 1500) {
    salario_libras = salario_libras * 260;
} else if (salario_libras > 1500 && salario_libras <= 10000) {
    salario_libras = salario_libras * 12;
}

let salario_euros = Math.round(salario_libras * 1.17);

// 3. NORMALIZAÇÃO DE LOCALIZAÇÃO (Filtro Supremo)
let localizacao_original = vaga.locationName || "Desconhecido";
let locLower = localizacao_original.toLowerCase();

// Regra base: Tudo é assumido como Reino Unido (mata códigos postais e cidades inglesas)
let pais_final = "United Kingdom";

// Exceção: Apenas se detetar a Irlanda é que altera
if (locLower.includes("ireland") || locLower.includes("dublin") || locLower.includes("cork") || locLower.includes("galway")) {
    pais_final = "Ireland";
}

// 4. MAPEAR PARA O POSTGRESQL E TELEGRAM (Array exato de 5 posições)
let valores = [
    vaga.jobTitle,
    pais_final,      // $2
    salario_euros,   // $3
    "Mid",           // $4
    "Mercado Local / Standard" // $5
];

msg.payload = valores;
return msg;

// Recuperar os dados com base no array de 6 posições revelado no debug
let titulo = msg.payload[0] || "Desconhecido";
let pais = msg.payload[1] || "Desconhecido";
let salario = Number(msg.payload[2]) || 0;

// Extrair mais informações com base nas posições reveladas no teu array
let experiencia = msg.payload[3] || "N/A";
let mercado = msg.payload[4] || "N/A";

// Aceder à memória do Node-RED para ver quantas vagas já foram geradas (inicia a 0)
let totalAlertas = context.get("contadorVagas") || 0;

// 1. DEFINIR O QUE É UM "VALOR ALTO" (Ex: Salário >= 100.000€)
let isValorAlto = salario >= 100000;

// 2. DEFINIR O QUE É UM "ROLE INCOMUM"
let keywordsRaras = ["cobol", "rust", "blockchain", "machine learning", "quantum", "fortran", "elixir", "power electronics"];
let isRoleIncomum = keywordsRaras.some(palavra => titulo.toLowerCase().includes(palavra));

// 3. SE CUMPRIR UMA DAS REGRAS, GERA O ALERTA
if (isValorAlto || isRoleIncomum) {

    // Aumenta o contador de vagas destacadas e guarda o novo valor na memória
    totalAlertas++;
    context.set("contadorVagas", totalAlertas);

    // Identificar o motivo do alerta
    let motivo = isValorAlto ? "💰 Alto Valor Financeiro" : "🦄 Vaga Incomum/Rara";
    if (isValorAlto && isRoleIncomum) motivo = "🔥 Jackpot (Rara + Alto Valor)";

    // Estruturar a mensagem para o Telegram com mais detalhes e rodapé
    msg.payload = {
        chat_id: env.get("TELEGRAM_CHAT_ID"),
        text: `🚨 *ALERTA DE VAGA DESTACADA* 🚨\n` +
              `*Motivo:* ${motivo}\n\n` +
              `📋 *Principais Infos:*\n` +
              `• *Cargo:* ${titulo}\n` +
              `• *País:* ${pais}\n` +
              `• *Nível:* ${experiencia}\n` +
              `• *Mercado:* ${mercado}\n` +
              `• *Salário Anual:* ${salario} €\n\n`,
        parse_mode: "Markdown"
    };

    // URL construido a partir do .env (o token NUNCA fica no flows.json)
    msg.url = "https://api.telegram.org/bot" + env.get("TELEGRAM_BOT_TOKEN") + "/sendMessage";

    return msg; 
}

// Se não for destacada, ignora
return null;

let dados = msg.payload;

// 1. Converter o Buffer para texto
if (Buffer.isBuffer(dados)) {
    dados = dados.toString();
}

// 2. Converter o texto de volta para Array
if (typeof dados === 'string') {
    try {
        dados = JSON.parse(dados);
    } catch (e) {
        return null; // Descarta se não for JSON válido
    }
}

// 3. Garantir que é mesmo um array (protege contra erros antigos na fila)
if (!Array.isArray(dados)) {
    return null;
}

// 4. Parâmetros blindados com valores por defeito para evitar erros de SQL
let parametrosFinais = [
    dados[0] || "Sem Titulo", 
    dados[1] || "Desconhecido", 
    Number(dados[2]) || 0,      
    dados[3] || "N/A",          
    dados[4] || "N/A"           
];

msg.params = parametrosFinais;
msg.payload = parametrosFinais; 

return msg;
